<?php
declare(strict_types=1);
require __DIR__ . '/src/bootstrap.php';
user_required();
$search = is_string($_GET['q'] ?? null) ? mb_substr(trim($_GET['q']),0,100) : '';
$sort = is_string($_GET['sort'] ?? null) ? $_GET['sort'] : 'newest';
$sorts = ['newest' => 'الأحدث أولًا','oldest' => 'الأقدم أولًا','name_asc' => 'الاسم تصاعديًا','name_desc' => 'الاسم تنازليًا'];
if (!isset($sorts[$sort])) $sort = 'newest';
$page = filter_var($_GET['page'] ?? 1, FILTER_VALIDATE_INT) ?: 1;
$result = (new Madar\StudentRepository())->page($search, $sort, $page);
$url = static fn(int $number): string => 'view_students.php?' . http_build_query(['q' => $search, 'sort' => $sort, 'page' => $number]);
Madar\View::start('دليل الطلاب', 'students');
?>
<header class="page-heading"><div><h1>دليل الطلاب <span class="count-badge"><?= $result['total'] ?></span></h1></div><a class="btn btn-primary" href="add_student.php"><?= Madar\View::icon('plus') ?>تسجيل طالب</a></header>
<section class="surface registry"><form method="get" class="registry-tools" role="search"><div class="search-field"><label class="visually-hidden" for="q">البحث عن طالب</label><?= Madar\View::icon('search') ?><input class="form-control" id="q" name="q" value="<?= e($search) ?>" maxlength="100" placeholder="ابحث بالاسم أو البريد أو الهاتف"></div><div class="sort-field"><label for="sort">الترتيب</label><select class="form-select" id="sort" name="sort"><?php foreach($sorts as $value => $label): ?><option value="<?= $value ?>" <?= $sort === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div><button class="btn btn-secondary" type="submit">بحث</button><?php if($search): ?><a class="text-link" href="view_students.php">مسح البحث</a><?php endif; ?></form>
<?php if(!$result['rows']): ?><div class="empty-state"><?= Madar\View::icon('users') ?><h2><?= $search ? 'لا توجد نتائج مطابقة' : 'الدليل جاهز لأول طالب' ?></h2><p><?= $search ? 'جرّب جزءًا آخر من الاسم أو البريد أو رقم الهاتف.' : 'سجل الطالب الأول لتبدأ بتنظيم البيانات.' ?></p><a class="btn btn-primary" href="<?= $search ? 'view_students.php' : 'add_student.php' ?>"><?= $search ? 'عرض كل الطلاب' : 'تسجيل طالب' ?></a></div><?php else: ?>
<div class="table-responsive"><table class="table student-table"><caption class="visually-hidden">سجلات الطلاب وبيانات التواصل وإجراءات التعديل والحذف</caption><thead><tr><th scope="col">الطالب</th><th scope="col">التواصل</th><th scope="col">العنوان</th><th scope="col">تاريخ الإضافة</th><th scope="col">الإجراءات</th></tr></thead><tbody>
<?php foreach($result['rows'] as $student): ?><tr><td><div class="student-identity"><?= Madar\View::avatar($student) ?><div><strong><?= e($student['name']) ?></strong><small>سجل <?= (int)$student['id'] ?></small></div></div></td><td data-label="التواصل"><a class="contact-link" href="mailto:<?= e($student['email']) ?>" dir="ltr"><?= e($student['email']) ?></a><span class="phone-text" dir="ltr"><?= e($student['phone']) ?></span></td><td data-label="العنوان"><span class="address-cell"><?= e($student['address']) ?></span></td><td data-label="أضيف في"><time datetime="<?= e(substr($student['created_at'],0,10)) ?>"><?= e(substr($student['created_at'],0,10)) ?></time></td><td class="row-actions"><a class="action-link" href="update_student.php?id=<?= (int)$student['id'] ?>" aria-label="تعديل <?= e($student['name']) ?>"><?= Madar\View::icon('edit') ?><span>تعديل</span></a><a class="action-link danger-text" href="delete_student.php?id=<?= (int)$student['id'] ?>" aria-label="حذف <?= e($student['name']) ?>"><?= Madar\View::icon('trash') ?><span>حذف</span></a></td></tr><?php endforeach; ?>
</tbody></table></div><div class="registry-bottom"><p>عرض <?= ($result['page']-1)*10+1 ?> إلى <?= min($result['page']*10,$result['total']) ?> من <?= $result['total'] ?> طالبًا</p><nav class="pagination-nav" aria-label="صفحات دليل الطلاب"><?php if($result['page']>1): ?><a class="btn btn-light" href="<?= e($url($result['page']-1)) ?>">السابق</a><?php else: ?><span class="btn btn-light disabled" aria-disabled="true">السابق</span><?php endif; ?><span>صفحة <?= $result['page'] ?> من <?= $result['pages'] ?></span><?php if($result['page']<$result['pages']): ?><a class="btn btn-light" href="<?= e($url($result['page']+1)) ?>">التالي</a><?php else: ?><span class="btn btn-light disabled" aria-disabled="true">التالي</span><?php endif; ?></nav></div><?php endif; ?></section>
<?php Madar\View::end(); ?>
